// ---- story (chapter Ch8 part 8a, ch8a agent: Sapphire's story scripts of this room; generators must keep
// everything from this line on; entries above marked "// story:")
// Sapphire data/maps/LilycoveCity_CoveLilyMotel_2F/scripts.inc: the Game Freak staff (hidden by
// FLAG_HIDE_LILYCOVE_MOTEL_PEOPLE until Ch11's Hall of Fame). People: data/story/ch8a.json. Lines 1-7 of the text file.
// The Game Designer's diploma: Sapphire checks the Hoenn Pokedex (200 species, national numbers from
// gHoennToNationalOrder) as caught; Black 2's own diploma screen (CallPokedexDiploma) is the closest to
// ScrSpecial_ShowDiploma (it is Black 2's Unova diploma picture).
#define T_ShowMeCompletedDex 1
#define T_FilledPokedex 2
#define T_Programmer 3
#define T_GraphicArtist 4
#define T_GirlsAreCute 5
#define T_SeaBreeze 6
#define T_GameBoy 7
#define M2_TEMP_FLAG 3                      // FLAG_TEMP_2 (Black 2 clears flags 0-0x63 on every map change)
MO2_GameDesigner:                           // ..._EventScript_GameDesigner
    c3_talk
    h_goto_if_set M2_TEMP_FLAG, L_MO2_ShowDiploma
    h_msgbox T_ShowMeCompletedDex
    VMCall Sub_MO2_CompletedHoennDex       // specialvar VAR_RESULT, CompletedHoennPokedex -> C8_A
    h_goto_if_eq C8_A, 1, L_MO2_Fanfare
    h_release
L_MO2_Fanfare:                              // ..._EventScript_AllHoennMonsFanfare
    h_setflag M2_TEMP_FLAG
    h_playfanfare MUS_OBTAIN_ITEM
    h_waitfanfare
L_MO2_ShowDiploma:                          // ..._EventScript_ShowDiploma
    ParentActorMsg MSGFILE_SCRIPT, T_FilledPokedex, 0, 0
    h_badge_fanfare                         // Common_EventScript_PlayGymBadgeFanfare
    MsgWinCloseAll
    FadeOutBlackQ
    FadeWait
    FieldClose
    CallPokedexDiploma 0, 0                 // special ScrSpecial_ShowDiploma
    FieldOpen
    FadeInBlackQ
    FadeWait
    h_release

MO2_GraphicArtist:
    h_msgbox_npc T_GraphicArtist
MO2_FatMan:
    h_msgbox_npc T_GirlsAreCute
MO2_Programmer:
    h_msgbox_npc T_Programmer
MO2_GameBoyKid:
    h_msgbox_npc T_GameBoy
MO2_Woman:
    h_msgbox_npc T_SeaBreeze
