// EMERALD (emerald_ch45_magma 2026-10-12; pokeemerald LilycoveCity_CoveLilyMotel_2F_EventScript_Scott): Scott dozes in the motel (he
// is there from the start; the Slateport harbor scene hides him, FLAG_HIDE_LILYCOVE_MOTEL_SCOTT). The first talk is the one that
// counts (VAR_SCOTT_STATE + 1, FLAG_MET_SCOTT_IN_LILYCOVE), the later ones are his Contest remark. Text: src/text/script/emerald/
// 0238_room_LilycoveCity_CoveLilyMotel_2F.txt lines 8 and 9 (the staff's lines 1-7 are Emerald's too).
#define T_ScottSnoozing 8
#define T_ScottStrategy 9
MO2_Scott:
    c3_talk
    h_goto_if_set FLAG_MET_SCOTT_IN_LILYCOVE, L_MO2_ScottMet
    h_msgbox T_ScottSnoozing            // Scott: ... Zzz... Huh?! Oh, sorry, sorry! I was snoozing! I came to check out this Pokémon Contest thing. ...
    h_addvar VAR_SCOTT_STATE, 1
    h_setflag FLAG_MET_SCOTT_IN_LILYCOVE
    h_release
L_MO2_ScottMet:
    h_msgbox T_ScottStrategy            // Scott: I think it does take strategy to win a Contest. ...
    h_release
#endif

